    if(el.dataset.market&&state.route==='markets'){state.activeMarket=Math.max(0,marketRows.findIndex(r=>r[0]===el.dataset.market));renderView();document.querySelector('[data-market="'+el.dataset.market+'"]')?.focus();return}
