      if(first){first.focus();return}
      document.getElementById('ticket-result').innerHTML='<div class="research-status" role="status"><h3>Ticket details are ready</h3><p>Submission is not connected in this preview. No ticket has been created; your entered details remain available.</p></div>';notice('No ticket submitted. This is a local design preview.');
